        }
        #chatInput {
            background: transparent; border: none; outline: none; resize: none; color: white;
            font-size: 0.9rem; flex-grow: 1; padding: 8px 10px; max-height: 120px;
        }
        #sendBtn {
            width: 38px; height: 38px; border-radius: 50%;
            background: linear-gradient(135deg, #667eea, #764ba2);
            color: white; flex-shrink: 0; display: flex; align-items: center; justify-content: center;
            transition: all 0.3s ease; transform: scale(0.9); opacity: 0.5;
        }
        #sendBtn:not(:disabled) { transform: scale(1); opacity: 1; }
        #sendBtn i { transition: transform 0.2s ease; }
        #sendBtn:not(:disabled):active i { transform: scale(0.9) rotate(10deg); }

        /* 3D Avatár konténer */
        .ai-icon-container {
            width: 40px; height: 40px; flex-shrink: 0; position: relative;
        }
        .ai-icon-canvas { width: 100% !important; height: 100% !important; }

        /* Képgenerálás stílusok */
        .generated-image { max-width: 100%; border-radius: 12px; margin-top: 8px; }
        .loader {
            width: 18px; height: 18px; border: 2px solid rgba(255,255,255,0.3);
            border-left-color: #fff; border-radius: 50%; display: inline-block;
            animation: spin 1s linear infinite; margin-right: 8px;
        }
        @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
    </style>
</head>
