<script>
    // --- API KONFIGURÁCIÓ ---
    // FIGYELEM: Az API kulcsot soha ne tárolja kliensoldali kódban éles környezetben!
    // Ezt egy biztonságos backend szerverről kellene lekérni.
    const API_KEY = 'YOUR_API_KEY'; // CSERÉLD LE A SAJÁT GOOGLE AI KULCSODRA
    const IMAGE_API_URL = ``;

    // --- DOM ELEMEK ---
    const chatInput = document.getElementById('chatInput');
    const sendBtn = document.getElementById('sendBtn');
    const chatView = document.getElementById('chatView');

    // --- 3D AVATÁR INICIALIZÁLÁSA (THREE.JS) ---
    function initAuraSphere(canvas) {
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, canvas.clientWidth / canvas.clientHeight, 0.1, 1000);
        camera.position.z = 1.5;

        const renderer = new THREE.WebGLRenderer({ canvas: canvas, alpha: true });
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.setSize(canvas.clientWidth, canvas.clientHeight);

        const sphereGeo = new THREE.IcosahedronGeometry(0.8, 20);

        const uniforms = {
            time: { value: 0 },
            colorA: { value: new THREE.Color("#667eea") },
            colorB: { value: new THREE.Color("#764ba2") }
        };

        const vertexShader = `
            uniform float time;
            varying vec3 vNormal;
            varying vec3 vPosition;
            void main() {
                vNormal = normal;
                vPosition = position;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position + normal * sin(position.y * 4.0 + time * 2.0) * 0.05, 1.0);
            }
        `;

        const fragmentShader = `
            uniform float time;
            uniform vec3 colorA;
            uniform vec3 colorB;
            varying vec3 vNormal;
            varying vec3 vPosition;
            void main() {
                float intensity = pow(0.6 - dot(vNormal, vec3(0.0, 0.0, 1.0)), 2.0);
                vec3 finalColor = mix(colorA, colorB, (sin(vPosition.y * 2.0 + time) + 1.0) / 2.0);
                gl_FragColor = vec4(finalColor, 1.0) * intensity;
            }
        `;

        const material = new THREE.ShaderMaterial({
            uniforms,
            vertexShader,
            fragmentShader,
            blending: THREE.AdditiveBlending,
            transparent: true,
        });

        const sphere = new THREE.Mesh(sphereGeo, material);
        scene.add(sphere);

        const clock = new THREE.Clock();
        function animate() {
            requestAnimationFrame(animate);
            uniforms.time.value = clock.getElapsedTime();
            sphere.rotation.y += 0.002;
            renderer.render(scene, camera);
        }
        animate();
    }

    document.addEventListener('DOMContentLoaded', () => {
        document.querySelectorAll('.ai-icon-canvas').forEach(canvas => {
            initAuraSphere(canvas);
        });
    });

    // --- ÜZENETKÜLDÉS LOGIKA ---
    function autoResize(textarea) {
        textarea.style.height = 'auto';
        textarea.style.height = textarea.scrollHeight + 'px';
    }

    chatInput.addEventListener('input', () => {
        sendBtn.disabled = chatInput.value.trim().length === 0;
        autoResize(chatInput);
    });

    sendBtn.addEventListener('click', () => sendMessage());
    chatInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            if (!sendBtn.disabled) sendMessage();
        }
    });

    function escapeHtml(text) {
        return text.replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'})[m]);
    }

    function appendMessage(isUser, content, id = null) {
        const bubble = document.createElement('div');
        bubble.className = `flex gap-3 chat-bubble ${isUser ? 'justify-end' : ''}`;
        if (id) bubble.id = id;

        const userIcon = `
            <div class="w-10 h-10 bg-purple-600 rounded-full flex items-center justify-center flex-shrink-0">
                <i class="fas fa-user text-sm"></i>
            </div>`;

        const aiIcon = `<div class="ai-icon-container"><canvas class="ai-icon-canvas"></canvas></div>`;

        const messageContent = `
            <div class="flex-1 max-w-[85%] ${isUser ? 'text-right' : ''}">
                <div class="${isUser ? 'bg-gradient-to-r from-purple-600 to-indigo-600' : 'bg-[rgba(0,0,0,0.4)]'} rounded-2xl ${isUser ? 'rounded-tr-md' : 'rounded-tl-md'} p-4 glass-effect inline-block break-words whitespace-pre-wrap">
                    ${content}
                </div>
            </div>`;

        bubble.innerHTML = isUser ? messageContent + userIcon : aiIcon + messageContent;
        chatView.appendChild(bubble);
        if(!isUser) {
             initAuraSphere(bubble.querySelector('.ai-icon-canvas'));
        }
        chatView.scrollTop = chatView.scrollHeight;
        return bubble;
    }

    async function sendMessage() {
        const message = chatInput.value.trim();
        if (message.length === 0) return;

        appendMessage(true, escapeHtml(message));

        chatInput.value = '';
        sendBtn.disabled = true;
        autoResize(chatInput);

        const lowerCaseMessage = message.toLowerCase();
        if (lowerCaseMessage.startsWith('generálj egy képet:')) {
            const prompt = message.substring('generálj egy képet:'.length).trim();
            handleImageGeneration(prompt);
        } else {
            handleStandardResponse(message);
        }
    }

    function handleStandardResponse(message) {
        setTimeout(() => {
             appendMessage(false, `Feldolgozom a kérést: "${escapeHtml(message)}". Hamarosan válaszolok.`);
        }, 800);
    }

    async function handleImageGeneration(prompt) {
        if (API_KEY === 'YOUR_API_KEY') {
            appendMessage(false, "Hiba: Az API kulcs nincs beállítva. Kérlek, add meg a `YOUR_API_KEY` helyére a szkriptben a kulcsodat.");
            return;
        }

        const responseId = 'response-' + Date.now();
        const loadingMessage = `<div class="flex items-center"><span class="loader"></span><span>Kép generálása...</span></div>`;
        const responseBubble = appendMessage(false, loadingMessage, responseId);

        try {
            const requestBody = {
                "instances": [{ "prompt": prompt }],
                "parameters": { "sampleCount": 1 }
            };

            const response = await fetch(IMAGE_API_URL, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(requestBody)
            });

            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.error.message || `HTTP hiba: ${response.status}`);
            }

            const data = await response.json();
            const imageBase64 = data.predictions[0].bytesBase64Encoded;

            const imageContent = `<p class="text-sm text-white/80 mb-2">Kép sikeresen generálva a következő alapján: "${escapeHtml(prompt)}"</p><img src="data:image/png;base64,${imageBase64}" alt="Generált kép" class="generated-image"/>`;
            responseBubble.querySelector('.inline-block').innerHTML = imageContent;

        } catch (error) {
            console.error("Képgenerálási hiba:", error);
            responseBubble.querySelector('.inline-block').innerHTML = `Hiba történt a kép generálása során. (${error.message})`;
        }
    }
</script>
</body>
</html>

