    // --- KÉPGENERÁLÓ MODÁLIS LOGIKA ---
    const imageModal = document.getElementById('imageModal');
    const openImageModalBtn = document.getElementById('openImageModal');
    const cancelImageModalBtn = document.getElementById('cancelImageModal');
    const generateImageBtn = document.getElementById('generateImageBtn');
    const appearanceInput = document.getElementById('appearance');
    const sceneInput = document.getElementById('scene');
    const imageModalError = document.getElementById('imageModalError');

    openImageModalBtn.addEventListener('click', () => {
        imageModal.style.display = 'flex';
        appearanceInput.value = '';
        sceneInput.value = '';
        imageModalError.style.display = 'none';
    });

    cancelImageModalBtn.addEventListener('click', () => {
        imageModal.style.display = 'none';
    });

    generateImageBtn.addEventListener('click', () => {
        const appearance = appearanceInput.value.trim();
        const scene = sceneInput.value.trim();

        if (!appearance || !scene) {
            imageModalError.textContent = 'Kérlek töltsd ki mindkét mezőt!';
            imageModalError.style.display = 'block';
            return;
        }
        imageModalError.style.display = 'none';
        imageModal.style.display = 'none';

        const prompt = `${appearance}, ${scene}, high quality, natural lighting, photorealistic`;
        handleImageGeneration(prompt);
    });

    // --- KÉPGENERÁLÁS FÜGGVÉNY ---
    async function handleImageGeneration(prompt) {
        if (API_KEY === 'YOUR_API_KEY') {
            appendMessage(false, "Hiba: Az API kulcs nincs beállítva. Kérlek, add meg a `YOUR_API_KEY` helyére a kulcsodat.");
            return;
        }

        const responseId = 'response-' + Date.now();
        const loadingMessage = `<div class="flex items-center"><span class="loader"></span><span>Kép készítése folyamatban...</span></div>`;
        const responseBubble = appendMessage(false, loadingMessage, responseId);

        try {
            const requestBody = {
                "instances": [{ "prompt": prompt }],
                "parameters": { "sampleCount": 1 }
            };

            const response = await fetch(IMAGE_API_URL, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(requestBody)
            });

            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.error.message || `HTTP hiba: ${response.status}`);
            }

            const data = await response.json();
            const imageBase64 = data.predictions[0].bytesBase64Encoded;

            const imageContent = `<p class="text-sm text-white/80 mb-2">Kép sikeresen generálva a következő alapján: "${escapeHtml(prompt)}"</p><img src="data:image/png;base64,${imageBase64}" alt="Generált kép" class="generated-image"/>`;
            responseBubble.querySelector('.inline-block').innerHTML = imageContent;

        } catch (error) {
            responseBubble.querySelector('.inline-block').innerHTML = `Hiba történt a kép generálása során. (${error.message})`;
        }
    }

